#include <wchar.h>


void CWE401_Memory_Leak__malloc_realloc_twoIntsStruct_01_bad()
{
    {
        twoIntsStruct * data = (twoIntsStruct *)malloc(100*sizeof(twoIntsStruct));
        if (data == NULL) {exit(-1);}

        data[0].intOne = 0;
        data[0].intTwo = 0;
        printStructLine(&data[0]);

        twoIntsStruct * temp = (twoIntsStruct *)realloc(data, (130000)*sizeof(twoIntsStruct));
        if (temp != NULL)
        {
            data = temp;
            data[0].intOne = 1;
            data[0].intTwo = 1;
            printStructLine(&data[0]);
            free(data);
        }
        else
        {
            free(data);
        }
    }
}
"}], "explanation": "The original code overwrote the only pointer to the malloc'd buffer with realloc's result. If realloc fails it returns NULL, leaking the original allocation. Using a temporary pointer preserves the original pointer so it can be freed on both success and failure paths, while keeping identical output."}
